using namespace Snatcher;
namespace {
unsigned checks=0;
void check(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"FAIL %s\n",why);std::exit(1);}}
void w(std::vector<uint8_t>&b,size_t p,uint16_t v){b[p]=uint8_t(v>>8);b[p+1]=uint8_t(v);}
void l(std::vector<uint8_t>&b,size_t p,uint32_t v){w(b,p,uint16_t(v>>16));w(b,p+2,uint16_t(v));}
std::vector<uint8_t> fixture(){std::vector<uint8_t>b(0x1400,0);l(b,0,0x2800c);l(b,4,0x28d0e);l(b,8,0x290d4);unsigned hs[]={0x291d4,0x29310,0x291da,0x29310,0x291e0,0x29310,0x291e6,0x29310,0x291ec,0x29310,0x291f2,0x29310,0x291f8,0x292e6,0x291fe,0x292f4,0x29204,0x2920a,0x2923a,0x29250,0x2925c,0x29266,0x29280,0x2928c,0x29280,0x29298,0x292ae,0x292bc};for(unsigned i=0;i<28;++i)w(b,0x10fc+i*6,uint16_t(hs[i]-0x290fc));return b;}
void run(const std::vector<uint8_t>& b,bool alternate){CreditsTimeline t;std::string e;std::vector<CreditsEvent> out;CreditsInput in;check(t.start(b,alternate,e),"start source");check(t.active()&&!t.finished()&&t.index()==-1,"initial owner");check(t.tick(in,out,e)&&out.empty(),"not ready freezes");in.ready=true;in.paused=true;check(t.tick(in,out,e)&&out.empty(),"paused freezes");in.paused=false;check(t.tick(in,out,e)&&out.size()==1&&out[0].kind==kCreditsStartTrack&&out[0].value==19,"actual CD19 request");check(t.tick(in,out,e)&&out.empty()&&t.index()==-1,"wait actual playing");in.cdPlaying=true;check(t.tick(in,out,e)&&out.size()==1&&out[0].kind==kCreditsResetRelativeClock&&t.index()==0,"playing acknowledges/reset only");check(t.tick(in,out,e)&&out.empty()&&t.index()==0,"unknown clock waits");in.clockKnown=true;in.relativeClock=0x99007400;
unsigned scenes=0;while(t.index()<17){check(t.tick(in,out,e),"timed row");for(auto a:out)if(a.kind==kCreditsInstallScene){check(a.value==scenes,"authored scene order");++scenes;}}check(scenes==9,"all timed scenes0..8");check(t.tick(in,out,e)&&t.index()==17,"credits waits CD drain despite final deadline");in.cdPlaying=false;in.cdIdleOrPaused=true;check(t.tick(in,out,e)&&t.countdown()==300&&t.index()==(alternate?24:18),"CD drain owns branch/countdown");
if(!alternate){for(unsigned i=0;i<299;++i)check(t.tick(in,out,e)&&t.index()==18,"300 count literal");check(t.tick(in,out,e)&&t.index()==19&&t.countdown()==64&&out.size()==1&&out[0].kind==kCreditsPalette&&out[0].value==0x12e2,"fade64 event");for(unsigned i=0;i<64;++i)check(t.tick(in,out,e),"64 count");check(t.index()==20,"fixed fade count end");check(t.tick(in,out,e)&&out.size()==1&&out[0].kind==kCreditsStartTrack&&out[0].value==2,"CD2 request");check(t.tick(in,out,e)&&t.index()==21,"CD2 real playing wait");in.cdPlaying=true;in.cdIdleOrPaused=false;check(t.tick(in,out,e)&&t.index()==22&&t.countdown()==24,"CD2 acknowledged");for(unsigned i=0;i<24;++i)check(t.tick(in,out,e),"24 count");check(t.tick(in,out,e)&&t.index()==24&&out.size()==1&&out[0].kind==kCreditsInstallScene&&out[0].value==9,"scene9 actual install");}
for(unsigned i=0;i<300;++i)check(t.tick(in,out,e),"300 before Start");check(t.waitingStart(),"ordinary Start gate");check(t.tick(in,out,e)&&t.waitingStart()&&out.empty(),"absent pressed edge waits");in.paused=true;in.startPressed=true;check(t.tick(in,out,e)&&t.waitingStart(),"paused edge not consumed");in.paused=false;check(t.tick(in,out,e)&&t.index()==26&&t.countdown()==64&&out.size()==1&&out[0].kind==kCreditsPalette,"new Start publishes fade");in.startPressed=false;for(unsigned i=0;i<64;++i)check(t.tick(in,out,e)&&t.active(),"final64 preserves application");check(t.tick(in,out,e)&&t.finished()&&!t.active()&&out.size()==1&&out[0].kind==kCreditsApplicationComplete,"completion handoff only");check(t.tick(in,out,e)&&out.empty(),"finished no duplicate event");}
}
int main(int argc,char**argv){auto b=fixture();run(b,false);run(b,true);std::string e;CreditsTimeline t;std::vector<CreditsEvent> out;check(t.start(b,false,e),"rollback seed");uint64_t stamp=t.sourceStamp();auto bad=b;w(bad,0x10fc,1);check(!t.start(bad,false,e)&&t.sourceStamp()==stamp,"unknown handler rollback");bad=b;l(bad,8,0x290d6);check(!t.start(bad,false,e)&&t.sourceStamp()==stamp,"wrong header rollback");bad=b;l(bad,0x10fe,0x00600000);check(!t.start(bad,false,e),"invalid BCD reject");bad.resize(100);check(!t.start(bad,false,e),"bounded source");l(b,0x10fe,0x00012000);check(t.start(b,false,e),"synthetic deadline");CreditsInput in;in.ready=true;check(t.tick(in,out,e),"deadline start");in.cdPlaying=true;check(t.tick(in,out,e),"deadline playing");in.clockKnown=true;in.relativeClock=0x00011900;check(t.tick(in,out,e)&&out.empty()&&t.index()==0,"deadline before boundary");in.relativeClock=0x00012000;check(t.tick(in,out,e)&&out.size()==1&&out[0].kind==kCreditsInstallScene&&t.index()==1,"exact BCD boundary one action");in.relativeClock=1;out.assign(1,CreditsEvent(kCreditsStartTrack,99));check(!t.tick(in,out,e)&&t.index()==1&&out[0].value==99,"invalid clock transactional output");if(argc==3&&std::string(argv[1])=="--original"){std::ifstream f(argv[2],std::ios::binary);std::vector<uint8_t> original((std::istreambuf_iterator<char>(f)),std::istreambuf_iterator<char>());run(original,false);run(original,true);std::puts("Original owner-provided Y16 semantic timeline PASS");}std::printf("Credits timeline: %u checks,0 failures\n",checks);return 0;}
